1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中销毁数量与交接关联是否一致。
70	//
71	// 每个样品先核对待确认交接，再核对销毁数量：已销毁样品仍挂着待确认交接
72	// 本身就是损坏，沿用原有的交接恢复报错。
73	//
74	// 对带有销毁信息的样品，逐一核对数量守恒（见 validateDestroyedQuantity）：
75	// 当前剩余量必须为 0.000，实际销毁量与自身初始量都大于零，且实际销毁量
76	// 加上各直接子样创建时取得的初始量之和恰好等于该样品自身的初始量。这里
77	// 只统计直接子样创建时的量：子样后来继续分装、转交或销毁都不改变原样
78	// 当时已经分出的量，不能改用子样当前剩余量，孙样也不重复计入；没有分出
79	// 子样的样品，实际销毁量就应等于自己的初始量。
80	//
81	// 样品的非空 PendingID 必须指向一条实际存在、尚未确认、且属于该样品的
82	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 PendingID 正好指向
83	// 它的样品。待确认交接表示样品当前全部剩余量尚待指定人员接收，因此其
84	// 内容还必须与样品当前记录一致：样品未销毁、剩余量大于零、交出人等于
85	// 当前持有人、交出地点等于当前地点、交接量精确等于当前剩余量。
86	//
87	// 已确认交接属于保留的历史，不要求样品继续指向它，也不核对其与样品当前
88	// 持有人、地点或剩余量的差异（样品后来分装、移动或销毁都不能否定当时的
89	// 接收事实）；但它必须保留有效的接收信息：确认人非空且与该交接原先指定
90	// 的接收人一致，接收时间存在且非零，且按实际时刻不早于交出时间（恰好
91	// 相等合法，时区只影响表示）。集合中占用编号却为 null 的条目视为损坏，
92	// 不能当作记录不存在。任一问题都使整个文件无法恢复，绝不只加载其中
93	// 一部分，也不改动原文件。
94	func validateRestored(l *ledger) error {
95		sampleIDs := make([]string, 0, len(l.Samples))
96		for id := range l.Samples {
97			sampleIDs = append(sampleIDs, id)
98		}
99		sort.Strings(sampleIDs)
100		for _, id := range sampleIDs {
101			rec := l.Samples[id]
102			if rec == nil {
103				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
104			}
105			if rec.PendingID != "" {
106				tr, ok := l.Transfers[rec.PendingID]
107				switch {
108				case !ok:
109					return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
110						ErrInvalid, id, rec.PendingID)
111				case tr == nil:
112					return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
113						ErrInvalid, id, rec.PendingID)
114				case tr.Confirmed:
115					return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
116						ErrInvalid, id, rec.PendingID)
117				case tr.SampleID != id:
118					return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
119						ErrInvalid, id, rec.PendingID, tr.SampleID)
120				}
121				if err := validatePendingContent(id, rec, tr); err != nil {
122					return err
123				}
124			}
125			// 销毁数量核对放在待确认交接核对之后：已销毁样品仍挂着待确认交接
126			// 本身就是损坏，沿用原有的交接恢复报错，保持与既有交接检查的兼容。
127			if rec.Destroyed != nil {
128				if err := validateDestroyedQuantity(id, rec, l); err != nil {
129					return err
130				}
131			}
132		}
133	
134		transferIDs := make([]string, 0, len(l.Transfers))
135		for id := range l.Transfers {
136			transferIDs = append(transferIDs, id)
137		}
138		sort.Strings(transferIDs)
139		for _, id := range transferIDs {
140			rec := l.Transfers[id]
141			if rec == nil {
142				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
143			}
144			if rec.Confirmed {
145				if err := validateConfirmedReceipt(rec); err != nil {
146					return err
147				}
148				continue
149			}
150			sample, ok := l.Samples[rec.SampleID]
151			switch {
152			case !ok:
153				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
154					ErrInvalid, id, rec.SampleID)
155			case sample == nil:
156				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
157					ErrInvalid, id, rec.SampleID)
158			case sample.PendingID != id:
159				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
160					ErrInvalid, id, rec.SampleID)
161			default:
162				if err := validatePendingContent(rec.SampleID, sample, rec); err != nil {
163					return err
164				}
165			}
166		}
167		return nil
168	}
169	
170	// validateDestroyedQuantity 核对一份带销毁信息的样品记录其数量是否守恒。
171	// 销毁处理的是样品当时的全部剩余量，因此恢复时必须满足：
172	//   - 当前剩余量为 0.000；
173	//   - 自身初始量与实际销毁量都大于零（参与核对的数量必须为正）；
174	//   - 实际销毁量加上它直接分出的各子样创建时取得的初始量之和，恰好等于
175	//     该样品自身的初始量。
176	//
177	// 直接子样总量取各子样记录自身的 Initial（创建时取得的量），只统计
178	// Children 中的直接子样：子样后来继续分装、转交或销毁都不改变原样当时
179	// 已经分出的量，不能改用子样当前剩余量，孙样也不重复计入。没有分出
180	// 子样时，直接子样总量为 0，实际销毁量就应等于自身初始量。同一份数据
181	// 里的其他原样不参与本次核对。合计超过 int64 可表示范围时按无效数据
182	// 拒绝，不能因数量过大把回绕后的差额当作合法结果接受。任一不符都返回
183	// 包装了 ErrInvalid 的错误，信息写明样品编号与数量不符的原因；涉及合计
184	// 不一致时同时展示初始量、销毁量与直接子样总量，统一按三位小数毫升展示。
185	func validateDestroyedQuantity(sampleID string, rec *sampleRecord, l *ledger) error {
186		const msgTail = "，无法恢复"
187		destroyedQty := rec.Destroyed.Qty
188		switch {
189		case rec.Remaining != 0:
190			return fmt.Errorf("%w: 样品 %q 已销毁但当前剩余量为 %s 毫升，已销毁样品剩余量必须为 0.000 毫升%s",
191				ErrInvalid, sampleID, formatUnits(rec.Remaining), msgTail)
192		case rec.Initial <= 0:
193			return fmt.Errorf("%w: 样品 %q 的销毁记录无法核对：样品初始量 %s 毫升必须大于零%s",
194				ErrInvalid, sampleID, formatUnits(rec.Initial), msgTail)
195		case destroyedQty <= 0:
196			return fmt.Errorf("%w: 样品 %q 的实际销毁量 %s 毫升必须大于零%s",
197				ErrInvalid, sampleID, formatUnits(destroyedQty), msgTail)
198		}
199	
200		// 只统计直接子样创建时取得的初始量；子样后续变化与孙样都不计入。
201		var directChildrenTotal int64
202		for _, childID := range rec.Children {
203			child, ok := l.Samples[childID]
204			if !ok || child == nil {
205				return fmt.Errorf("%w: 样品 %q 的直接子样 %q 不存在，无法核对销毁数量%s",
206					ErrInvalid, sampleID, childID, msgTail)
207			}
208			if child.Initial <= 0 {
209				return fmt.Errorf("%w: 样品 %q 的直接子样 %q 初始量 %s 毫升必须大于零，无法核对销毁数量%s",
210					ErrInvalid, sampleID, childID, formatUnits(child.Initial), msgTail)
211			}
212			next := directChildrenTotal + child.Initial
213			if next < 0 || next < directChildrenTotal {
214				return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，实际销毁量 %s 毫升与直接子样总量合计超出可表示范围%s",
215					ErrInvalid, sampleID, formatUnits(destroyedQty), msgTail)
216			}
217			directChildrenTotal = next
218		}
219	
220		total := destroyedQty + directChildrenTotal
221		if total < 0 || total < destroyedQty {
222			return fmt.Errorf("%w: 样品 %q 的销毁数量核对中，实际销毁量 %s 毫升与直接子样总量 %s 毫升合计超出可表示范围%s",
223				ErrInvalid, sampleID, formatUnits(destroyedQty),
224				formatUnits(directChildrenTotal), msgTail)
225		}
226		if total != rec.Initial {
227			return fmt.Errorf("%w: 样品 %q 的销毁数量与分装记录不符：初始量 %s 毫升，实际销毁量 %s 毫升，直接子样总量 %s 毫升，实际销毁量与直接子样总量之和应为 %s 毫升%s",
228				ErrInvalid, sampleID,
229				formatUnits(rec.Initial), formatUnits(destroyedQty),
230				formatUnits(directChildrenTotal), formatUnits(rec.Initial), msgTail)
231		}
232		return nil
233	}
234	
235	// validatePendingContent 核对一条待确认交接的内容是否与样品当前记录一致。
236	// 待确认交接表示样品当前全部剩余量尚待指定人员接收：样品必须未销毁且
237	// 剩余量大于零，交接的交出人、交出地点和交接量必须分别精确等于样品的
238	// 当前持有人、当前地点和当前剩余量。任一不符都返回包装了 ErrInvalid 的
239	// 错误，并在信息中写明样品编号、交接编号以及冲突项（人员、地点、数量
240	// 或销毁状态）；数量冲突同时列出双方数量，统一按三位小数毫升展示。
241	func validatePendingContent(sampleID string, sample *sampleRecord, tr *transferRecord) error {
242		switch {
243		case sample.Destroyed != nil:
244			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品已销毁，无法恢复",
245				ErrInvalid, sampleID, tr.ID)
246		case sample.Remaining <= 0:
247			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品当前剩余量为 %s 毫升（未销毁），无法恢复",
248				ErrInvalid, sampleID, tr.ID, formatUnits(sample.Remaining))
249		case tr.FromHolder != sample.Holder:
250			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出人 %q 与样品当前持有人 %q 不一致，无法恢复",
251				ErrInvalid, sampleID, tr.ID, tr.FromHolder, sample.Holder)
252		case tr.FromLocation != sample.Location:
253			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出地点 %q 与样品当前地点 %q 不一致，无法恢复",
254				ErrInvalid, sampleID, tr.ID, tr.FromLocation, sample.Location)
255		case tr.Qty != sample.Remaining:
256			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交接量 %s 毫升与样品当前剩余量 %s 毫升不一致，无法恢复",
257				ErrInvalid, sampleID, tr.ID, formatUnits(tr.Qty), formatUnits(sample.Remaining))
258		}
259		return nil
260	}
261	
262	// validateConfirmedReceipt 核对一条已确认交接是否保留了有效的接收事实。
263	// 已确认表示样品确实完成过一次转手，因此确认人必须非空（去首尾空白后）
264	// 且与该交接原先指定的接收人完全一致，接收时间必须存在且不是零时间，
265	// 并按实际时刻不早于交出时间（恰好相等合法；不同时区表示同一时刻也算
266	// 相等，时间倒置用 Before 判断而非比较时区偏移后的字面值）。任一不符
267	// 都返回包装了 ErrInvalid 的错误，信息写明交接编号、关联样品编号以及
268	// 具体问题（缺少/空白确认人、确认人不符、缺少或零值接收时间、时间倒置），
269	// 绝不靠补写确认人、猜测接收时间或改回待确认来接受异常记录。
270	func validateConfirmedReceipt(tr *transferRecord) error {
271		switch {
272		case tr.ConfirmedBy == "":
273			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少确认人，无法恢复",
274				ErrInvalid, tr.ID, tr.SampleID)
275		case strings.TrimSpace(tr.ConfirmedBy) == "":
276			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人不能只有空白，无法恢复",
277				ErrInvalid, tr.ID, tr.SampleID)
278		case tr.ConfirmedBy != tr.ToHolder:
279			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人 %q 与原定接收人 %q 不一致，无法恢复",
280				ErrInvalid, tr.ID, tr.SampleID, tr.ConfirmedBy, tr.ToHolder)
281		}
282		switch {
283		case tr.ReceivedAt == nil:
284			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少接收时间，无法恢复",
285				ErrInvalid, tr.ID, tr.SampleID)
286		case tr.ReceivedAt.IsZero():
287			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间为零值，无法恢复",
288				ErrInvalid, tr.ID, tr.SampleID)
289		case tr.ReceivedAt.Before(tr.HandedOverAt):
290			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间 %s 早于交出时间 %s，无法恢复",
291				ErrInvalid, tr.ID, tr.SampleID,
292				tr.ReceivedAt.Format(time.RFC3339), tr.HandedOverAt.Format(time.RFC3339))
293		}
294		return nil
295	}
