297	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
298	// 避免进程中断留下半截数据。
299	func (s *Store) persist(l *ledger) error {
300		raw, err := json.MarshalIndent(l, "", "  ")
301		if err != nil {
302			return fmt.Errorf("编码本地样品数据失败: %w", err)
303		}
304	
305		dir := filepath.Dir(s.path)
306		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
307		if err != nil {
308			return fmt.Errorf("创建临时数据文件失败: %w", err)
309		}
310		tmpName := tmp.Name()
311		defer os.Remove(tmpName)
312	
313		if _, err := tmp.Write(raw); err != nil {
314			tmp.Close()
315			return fmt.Errorf("写入临时数据文件失败: %w", err)
316		}
317		if err := tmp.Close(); err != nil {
318			return fmt.Errorf("关闭临时数据文件失败: %w", err)
319		}
320		if err := os.Rename(tmpName, s.path); err != nil {
321			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
322		}
323		return nil
324	}
325	
326	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
327	// 已通过全部校验；落盘失败时内存状态保持不变。
328	func (s *Store) commit(candidate *ledger) error {
329		if err := s.persist(candidate); err != nil {
330			return err
331		}
332		s.data = candidate
333		return nil
334	}
