336	// RegisterInput 是登记原样的入参。
337	type RegisterInput struct {
338		// ID 为样品编号，在这份数据内唯一，去空白后非空。
339		ID string
340		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
341		Qty string
