348	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
349	// 且不会写入任何记录。
350	func (s *Store) Register(in RegisterInput) (*Sample, error) {
351		s.mu.Lock()
352		defer s.mu.Unlock()
353	
354		id, err := trimRequired("样品编号", in.ID)
355		if err != nil {
356			return nil, err
357		}
358		holder, err := trimRequired("持有人", in.Holder)
359		if err != nil {
360			return nil, err
361		}
362		location, err := trimRequired("地点", in.Location)
363		if err != nil {
364			return nil, err
365		}
366		qty, err := parseQuantity(in.Qty)
367		if err != nil {
368			return nil, err
369		}
370		if _, exists := s.data.Samples[id]; exists {
371			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
372		}
373	
374		candidate := s.data.deepCopy()
375		now := s.now().UTC()
376		candidate.Samples[id] = &sampleRecord{
377			ID:        id,
378			Initial:   qty,
379			Remaining: qty,
380			Holder:    holder,
381			Location:  location,
382			Children:  []string{},
383			History: []historyRecord{{
384				Kind:     "register",
385				Time:     now,
386				Holder:   holder,
387				Location: location,
388				Detail:   "登记原样",
389			}},
390		}
391		if err := s.commit(candidate); err != nil {
392			return nil, err
393		}
394		return buildSampleView(candidate.Samples[id], candidate), nil
395	}
