397	// SplitPart 是一次分装中的一个子样。
398	type SplitPart struct {
399		// ID 为子样编号，在这份数据内唯一，去空白后非空。
400		ID string
401		// Qty 为该子样数量（毫升），大于零、最多三位小数。
402		Qty string
403	}
404	
405	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
406	type SplitInput struct {
407		// ParentID 为来源样品编号。
408		ParentID string
409		// Parts 为本次要创建的全部子样，至少一个。
410		Parts []SplitPart
411	}
412	
413	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
414	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
415	// 扣减，子样继承当时的持有人和地点，并可继续分装。
416	//
417	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
418	func (s *Store) Split(in SplitInput) (*Sample, error) {
419		s.mu.Lock()
420		defer s.mu.Unlock()
421	
422		parentID, err := trimRequired("来源样品编号", in.ParentID)
423		if err != nil {
424			return nil, err
425		}
426		if len(in.Parts) == 0 {
427			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
428		}
429	
430		parent, ok := s.data.Samples[parentID]
431		if !ok {
432			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
433		}
434	
435		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
436		type parsedPart struct {
437			id  string
438			qty int64
439		}
440		parsed := make([]parsedPart, 0, len(in.Parts))
441		seen := make(map[string]struct{}, len(in.Parts))
442		var total int64
443		for _, p := range in.Parts {
444			id, err := trimRequired("子样编号", p.ID)
445			if err != nil {
446				return nil, err
447			}
448			if _, dup := seen[id]; dup {
449				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
450			}
451			if _, exists := s.data.Samples[id]; exists {
452				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
453			}
454			if id == parentID {
455				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
456			}
457			qty, err := parseQuantity(p.Qty)
458			if err != nil {
459				return nil, err
460			}
461			seen[id] = struct{}{}
462			parsed = append(parsed, parsedPart{id: id, qty: qty})
463			total += qty
464			if total < 0 {
465				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
466			}
467		}
468	
469		if parent.Destroyed != nil {
470			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
471		}
472		if parent.PendingID != "" {
473			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
474				ErrConflict, parentID, parent.PendingID)
475		}
476		if parent.Remaining == 0 {
477			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
478		}
479		if total > parent.Remaining {
480			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
481				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
482		}
483	
484		candidate := s.data.deepCopy()
485		cpParent := candidate.Samples[parentID]
486		now := s.now().UTC()
487	
488		childIDs := make([]string, 0, len(parsed))
489		for _, p := range parsed {
490			childIDs = append(childIDs, p.id)
491			candidate.Samples[p.id] = &sampleRecord{
492				ID:        p.id,
493				ParentID:  parentID,
494				Initial:   p.qty,
495				Remaining: p.qty,
496				Holder:    cpParent.Holder,
497				Location:  cpParent.Location,
498				Children:  []string{},
499				History: []historyRecord{{
500					Kind:     "split",
501					Time:     now,
502					Holder:   cpParent.Holder,
503					Location: cpParent.Location,
504					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
505				}},
506			}
507		}
508		cpParent.Remaining -= total
509		cpParent.Children = append(cpParent.Children, childIDs...)
510		cpParent.History = append(cpParent.History, historyRecord{
511			Kind:     "split",
512			Time:     now,
513			Holder:   cpParent.Holder,
514			Location: cpParent.Location,
515			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
516		})
517	
518		if err := s.commit(candidate); err != nil {
519			return nil, err
520		}
521		return buildSampleView(cpParent, candidate), nil
522	}
523	
524	// HandoverInput 是发起交接（交出）的入参。
525	type HandoverInput struct {
526		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
527		TransferID string
528		// SampleID 为要交出的样品编号。
529		SampleID string
530		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
531		FromHolder string
532		// FromLocation 为交出地点，必须与样品当前地点完全一致。
533		FromLocation string
534		// ToHolder 为指定接收人，不能与交出人相同。
535		ToHolder string
536		// ToLocation 为目的地点。
537		ToLocation string
538		// HandedOverAt 为交出时间。
539		HandedOverAt time.Time
540	}
541	
542	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
543	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
544	//
545	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
546	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
547	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
548		s.mu.Lock()
549		defer s.mu.Unlock()
550	
551		transferID, err := trimRequired("交接编号", in.TransferID)
552		if err != nil {
553			return nil, err
554		}
555		sampleID, err := trimRequired("样品编号", in.SampleID)
556		if err != nil {
557			return nil, err
558		}
559		fromHolder, err := trimRequired("交出人", in.FromHolder)
560		if err != nil {
561			return nil, err
562		}
563		fromLocation, err := trimRequired("交出地点", in.FromLocation)
564		if err != nil {
565			return nil, err
566		}
567		toHolder, err := trimRequired("接收人", in.ToHolder)
568		if err != nil {
569			return nil, err
570		}
571		toLocation, err := trimRequired("目的地点", in.ToLocation)
572		if err != nil {
573			return nil, err
574		}
575		if in.HandedOverAt.IsZero() {
576			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
577		}
578		handedAt := in.HandedOverAt.UTC()
579	
580		if existing, ok := s.data.Transfers[transferID]; ok {
581			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
582				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
583			}
584			// 完全相同的重复提交：返回原交接，不增加任何记录。
585			return buildTransferView(existing), nil
586		}
587	
588		sample, ok := s.data.Samples[sampleID]
589		if !ok {
590			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
591		}
592		if sample.Destroyed != nil {
593			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
594		}
595		if sample.Remaining == 0 {
596			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
597		}
598		if sample.PendingID != "" {
599			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
600				ErrConflict, sampleID, sample.PendingID)
601		}
602		if sample.Holder != fromHolder {
603			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
604				ErrInvalid, fromHolder, sampleID, sample.Holder)
605		}
606		if sample.Location != fromLocation {
607			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
608				ErrInvalid, fromLocation, sampleID, sample.Location)
609		}
610		if toHolder == fromHolder {
611			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
612		}
613	
614		candidate := s.data.deepCopy()
615		rec := &transferRecord{
616			ID:           transferID,
617			SampleID:     sampleID,
618			FromHolder:   fromHolder,
619			FromLocation: fromLocation,
620			ToHolder:     toHolder,
621			ToLocation:   toLocation,
622			Qty:          sample.Remaining,
623			HandedOverAt: handedAt,
624		}
625		candidate.Transfers[transferID] = rec
626		cpSample := candidate.Samples[sampleID]
627		cpSample.PendingID = transferID
628		cpSample.History = append(cpSample.History, historyRecord{
629			Kind:     "transfer-out",
630			Time:     handedAt,
631			Holder:   fromHolder,
632			Location: fromLocation,
633			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
634		})
635	
636		if err := s.commit(candidate); err != nil {
637			return nil, err
638		}
639		return buildTransferView(rec), nil
640	}
641	
642	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
643	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
644		return t.SampleID == sampleID &&
645			t.FromHolder == fromHolder &&
646			t.FromLocation == fromLocation &&
647			t.ToHolder == toHolder &&
648			t.ToLocation == toLocation &&
649			t.HandedOverAt.Equal(handedAt)
650	}
651	
652	// ConfirmInput 是确认接收的入参。
653	type ConfirmInput struct {
654		// TransferID 为待确认的交接编号。
655		TransferID string
656		// Receiver 为实际接收人，必须是发起时指定的接收人。
657		Receiver string
658		// AtLocation 为接收地点，必须是发起时的目的地点。
659		AtLocation string
660		// ReceivedAt 为接收时间，不能早于交出时间。
661		ReceivedAt time.Time
662	}
663	
664	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
665	// 才真正改变，待确认状态结束。
666	//
667	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
668	// 返回原结果且不增加转手记录；信息不同则拒绝。
669	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
670		s.mu.Lock()
671		defer s.mu.Unlock()
672	
673		transferID, err := trimRequired("交接编号", in.TransferID)
674		if err != nil {
675			return nil, err
676		}
677		receiver, err := trimRequired("接收人", in.Receiver)
678		if err != nil {
679			return nil, err
680		}
681		atLocation, err := trimRequired("接收地点", in.AtLocation)
682		if err != nil {
683			return nil, err
684		}
685		if in.ReceivedAt.IsZero() {
686			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
687		}
688		receivedAt := in.ReceivedAt.UTC()
689	
690		rec, ok := s.data.Transfers[transferID]
691		if !ok {
692			// 明确的不存在错误，绝不顺带创建交接。
693			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
694		}
695	
696		if rec.Confirmed {
697			same := rec.ConfirmedBy == receiver &&
698				rec.ToLocation == atLocation &&
699				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
700			if !same {
701				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
702			}
703			return buildTransferView(rec), nil
704		}
705	
706		if receiver != rec.ToHolder {
707			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
708				ErrConflict, rec.ToHolder, transferID, receiver)
709		}
710		if atLocation != rec.ToLocation {
711			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
712				ErrConflict, rec.ToLocation, transferID, atLocation)
713		}
714		if receivedAt.Before(rec.HandedOverAt) {
715			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
716				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
717		}
718	
719		candidate := s.data.deepCopy()
720		cp := candidate.Transfers[transferID]
721		cp.Confirmed = true
722		cp.ConfirmedBy = receiver
723		receivedAtCopy := receivedAt
724		cp.ReceivedAt = &receivedAtCopy
725	
726		sample := candidate.Samples[cp.SampleID]
727		sample.Holder = receiver
728		sample.Location = atLocation
729		sample.PendingID = ""
730		sample.History = append(sample.History, historyRecord{
731			Kind:     "transfer-in",
732			Time:     receivedAt,
733			Holder:   receiver,
734			Location: atLocation,
735			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
736		})
737	
738		if err := s.commit(candidate); err != nil {
739			return nil, err
740		}
741		return buildTransferView(cp), nil
742	}
743	
744	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
745	type DestroyInput struct {
746		// SampleID 为样品编号。
747		SampleID string
748		// Operator 为操作人，去空白后必须与样品当前持有人一致。
749		Operator string
750		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
751		Location string
752		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
753		At time.Time
754		// Reason 为销毁原因，去空白后非空。
755		Reason string
756	}
757	
758	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
759	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
760	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
761	// 事件；返回该样品的最新查询结果。
762	//
763	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
764	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
765	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
766	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
767		s.mu.Lock()
768		defer s.mu.Unlock()
769	
770		sampleID, err := trimRequired("样品编号", in.SampleID)
771		if err != nil {
772			return nil, err
773		}
774		operator, err := trimRequired("操作人", in.Operator)
775		if err != nil {
776			return nil, err
777		}
778		location, err := trimRequired("所在地点", in.Location)
779		if err != nil {
780			return nil, err
781		}
782		reason, err := trimRequired("销毁原因", in.Reason)
783		if err != nil {
784			return nil, err
785		}
786		if in.At.IsZero() {
787			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
788		}
789		at := in.At.UTC()
790	
791		rec, ok := s.data.Samples[sampleID]
792		if !ok {
793			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
794		}
795	
796		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
797		if rec.Destroyed != nil {
798			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
799				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
800					ErrConflict, sampleID)
801			}
802			return buildSampleView(rec, s.data), nil
803		}
804	
805		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
806		if operator != rec.Holder {
807			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
808				ErrConflict, operator, sampleID, rec.Holder)
809		}
810		if location != rec.Location {
811			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
812				ErrConflict, location, sampleID, rec.Location)
813		}
814		if rec.PendingID != "" {
815			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
816				ErrConflict, sampleID, rec.PendingID)
817		}
818		if rec.Remaining == 0 {
819			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
820				ErrConflict, sampleID)
821		}
822		for _, h := range rec.History {
823			if at.Before(h.Time) {
824				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
825					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
826			}
827		}
828	
829		candidate := s.data.deepCopy()
830		cp := candidate.Samples[sampleID]
831		destroyedQty := cp.Remaining
832		cp.Remaining = 0
833		cp.Destroyed = &destructionRecord{
834			Operator: operator,
835			Location: location,
836			At:       at,
837			Reason:   reason,
838			Qty:      destroyedQty,
839		}
840		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
841		cp.History = append(cp.History, historyRecord{
842			Kind:     "destroy",
843			Time:     at,
844			Holder:   operator,
845			Location: location,
846			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
847		})
848	
849		if err := s.commit(candidate); err != nil {
850			return nil, err
851		}
852		return buildSampleView(cp, candidate), nil
853	}
854	
855	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
856	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
857	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
858		return d.Operator == operator &&
859			d.Location == location &&
860			d.At.Equal(at) &&
861			d.Reason == reason
862	}
863	
864	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
865	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
866	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
867	func (s *Store) GetSample(id string) (*Sample, error) {
868		s.mu.Lock()
869		defer s.mu.Unlock()
870	
871		sampleID, err := trimRequired("样品编号", id)
872		if err != nil {
873			return nil, err
874		}
875		rec, ok := s.data.Samples[sampleID]
876		if !ok {
877			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
878		}
879		return buildSampleView(rec, s.data), nil
880	}
881	
882	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
883	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
884	func (s *Store) GetTransfer(id string) (*TransferView, error) {
885		s.mu.Lock()
886		defer s.mu.Unlock()
887	
888		transferID, err := trimRequired("交接编号", id)
889		if err != nil {
890			return nil, err
891		}
892		rec, ok := s.data.Transfers[transferID]
893		if !ok {
894			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
895		}
896		return buildTransferView(rec), nil
897	}
898	
899	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
900	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
901		children := append([]string{}, r.Children...)
902		history := make([]History, 0, len(r.History))
903		for _, h := range r.History {
904			history = append(history, History{
905				Kind:     h.Kind,
906				Time:     h.Time,
907				Holder:   h.Holder,
908				Location: h.Location,
909				Detail:   h.Detail,
910			})
911		}
912		v := &Sample{
913			ID:         r.ID,
914			ParentID:   r.ParentID,
915			InitialQty: formatUnits(r.Initial),
916			Remaining:  formatUnits(r.Remaining),
917			Holder:     r.Holder,
918			Location:   r.Location,
919			Children:   children,
920			History:    history,
921		}
922		if r.PendingID != "" {
923			if t, ok := l.Transfers[r.PendingID]; ok {
924				v.PendingTransfer = buildTransferView(t)
925			}
926		}
927		if r.Destroyed != nil {
928			v.Destruction = &Destruction{
929				Operator: r.Destroyed.Operator,
930				Location: r.Destroyed.Location,
931				At:       r.Destroyed.At,
932				Reason:   r.Destroyed.Reason,
933				Qty:      formatUnits(r.Destroyed.Qty),
934			}
935		}
936		return v
937	}
938	
939	// buildTransferView 把内部交接记录转换为对外视图。
940	func buildTransferView(r *transferRecord) *TransferView {
941		v := &TransferView{
942			TransferID:   r.ID,
943			SampleID:     r.SampleID,
944			FromHolder:   r.FromHolder,
945			FromLocation: r.FromLocation,
946			ToHolder:     r.ToHolder,
947			ToLocation:   r.ToLocation,
948			Qty:          formatUnits(r.Qty),
949			HandedOverAt: r.HandedOverAt,
950			Confirmed:    r.Confirmed,
951			ConfirmedBy:  r.ConfirmedBy,
952		}
953		if r.ReceivedAt != nil {
954			rx := *r.ReceivedAt
955			v.ReceivedAt = &rx
956			v.ConfirmedAt = r.ToLocation
957		}
958		return v
959	}
960

