272		return writeRawLedger(t, content)
273	}
274	
275	func TestOpenRejectsPendingHandoverWithStaleQuantity(t *testing.T) {
276		// 待确认交接仍写着分出子样前的 10.000，而样品当前只剩 6.750。
277		stale := strings.Replace(consistentPendingTR, `"qty":6750`, `"qty":10000`, 1)
278		path := writeDivergedScenario(t, "6750", "", stale)
279		mustRejectOpen(t, path, "S-001", "TR-002", "交接量", "10.000", "6.750")
280	}
281	
282	func TestOpenRejectsPendingHandoverWithWrongHolder(t *testing.T) {
283		wrong := strings.Replace(consistentPendingTR, `"fromHolder":"李四"`, `"fromHolder":"张三"`, 1)
284		path := writeDivergedScenario(t, "", "", wrong)
285		mustRejectOpen(t, path, "S-001", "TR-002", "交出人", "持有人", "张三", "李四")
