292	}
293	
294	func TestOpenRejectsPendingHandoverForDestroyedSample(t *testing.T) {
295		extra := `,"destroyed":{"operator":"李四","location":"实验室B","at":"2026-10-03T08:00:00Z","reason":"实验结束按规程销毁","qty":6750}`
296		path := writeDivergedScenario(t, "", extra, "")
297		mustRejectOpen(t, path, "S-001", "TR-002", "销毁")
298	}
299	
300	func TestOpenRejectsPendingHandoverForZeroRemainingSample(t *testing.T) {
301		path := writeDivergedScenario(t, "0", "", "")
302		mustRejectOpen(t, path, "S-001", "TR-002", "0.000")
303	}
304	
305	// TestOpenRestoresConsistentPendingHandover 覆盖任务示例的合法分支：
306	// 待确认交接正确记录 6.750、当前持有人李四和地点实验室B 时正常恢复，
307	// 保持待确认状态，仍由指定接收人王五在目的地点实验室C 确认；旧交接
308	// TR-001 当时的 10.000 记录继续保留且可查询，不被拒绝或改写。
309	func TestOpenRestoresConsistentPendingHandover(t *testing.T) {
310		s, hAt1, rAt1, hAt2, rAt2 := setupDivergedHandover(t)
311	
312		s2, err := Open(s.path)
313		if err != nil {
314			t.Fatalf("内容一致的待确认交接应随文件正常恢复: %v", err)
315		}
316		p, err := s2.GetSample("S-001")
317		if err != nil {
318			t.Fatal(err)
319		}
320		requireParentMidSecondHandover(t, p, hAt2)
321	
322		old, err := s2.GetTransfer("TR-001")
