333			t.Fatalf("确认结果错误: %+v", done)
334		}
335		p, _ = s2.GetSample("S-001")
336		if p.Holder != "王五" || p.Location != "实验室C" || p.PendingTransfer != nil {
337			t.Fatalf("确认后持有人和地点才改变，待确认状态结束: %+v", p)
338		}
