50	func destroyedSample(id string, initial, remaining, destroyedQty int64, children ...string) *sampleRecord {
51		s := &sampleRecord{
52			ID:        id,
53			Initial:   initial,
54			Remaining: remaining,
55			Holder:    "李四",
56			Location:  "实验室B",
57			Children:  append([]string{}, children...),
58			History: []historyRecord{{
59				Kind: "register", Time: registerCheckAt, Holder: "李四", Location: "实验室B",
60			}},
61			Destroyed: &destructionRecord{
62				Operator: "李四",
63				Location: "实验室B",
64				At:       destroyedCheckAt,
65				Reason:   "实验结束按规程销毁",
66				Qty:      destroyedQty,
67			},
68		}
69		if len(children) > 0 {
70			s.History = append(s.History, historyRecord{
71				Kind: "split", Time: splitCheckAt, Holder: "李四", Location: "实验室B",
72			})
73		}
74		s.History = append(s.History, historyRecord{
75			Kind: "destroy", Time: destroyedCheckAt, Holder: "李四", Location: "实验室B",
76		})
77		return s
78	}
