262	// TestOpenDestroyedAccountingUsesChildInitialOnly 核对只取各直接子样创建
263	// 时的初始量：
264	//   - 孙样不重复计入：父样分出 4.000 给子样，子样又把 4.000 全部分给孙样，
265	//     父样销毁 6.000 仍满足 6.000 + 4.000 = 10.000；
266	//   - 子样后来继续分装、转交或销毁不改变父样已分出的量：子样当前只剩
267	//     2.250（自身又分出 1.000）或已全部销毁，父样仍按子样初始量 3.250 核
268	//     对，不能改用子样当前剩余量。
269	func TestOpenDestroyedAccountingUsesChildInitialOnly(t *testing.T) {
270		// 场景一：孙样不重复计入；子样分装用尽（无销毁信息）也合法。
271		grandchild := plainChild("G", "C", 4000, 4000)
272		childExhausted := plainChild("C", "P", 4000, 0)
273		childExhausted.Children = []string{"G"}
274		childExhausted.History = append(childExhausted.History, historyRecord{
275			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
276		})
277		l1 := &ledger{
278			Samples: map[string]*sampleRecord{
279				"P": destroyedSample("P", 10000, 0, 6000, "C"),
280				"C": childExhausted,
281				"G": grandchild,
282			},
283		}
284		if s, err := Open(writeStructLedger(t, l1)); err != nil {
285			t.Fatalf("孙样不得计入父样销毁核对，6.000+4.000=10.000 应恢复: %v", err)
286		} else {
287			p, _ := s.GetSample("P")
288			if p.Destruction == nil || p.Destruction.Qty != "6.000" {
289				t.Fatalf("父样销毁量恢复错误: %+v", p.Destruction)
290			}
291		}
292	
293		// 场景二：子样自己又分出 1.000，当前只剩 2.250；父样仍按子样初始量
294		// 3.250 核对（6.750 + 3.250 = 10.000）。
295		childSplit := plainChild("S-001-A", "S-001", 3250, 2250)
296		childSplit.Children = []string{"S-001-A-G"}
297		childSplit.History = append(childSplit.History, historyRecord{
298			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
299		})
300		l2 := &ledger{
301			Samples: map[string]*sampleRecord{
302				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
303				"S-001-A":   childSplit,
304				"S-001-A-G": plainChild("S-001-A-G", "S-001-A", 1000, 1000),
305			},
306		}
307		if _, err := Open(writeStructLedger(t, l2)); err != nil {
308			t.Fatalf("必须按子样创建时初始量 3.250 核对，不能用其当前剩余 2.250: %v", err)
309		}
310	
311		// 场景三：子样已独立销毁（销毁量取其当时剩余 2.250），父样核对仍按
312		// 子样初始量 3.250；父子销毁记录恢复后各自独立。
313		childDestroyed := destroyedSampleWithParent("S-001-A", "S-001", 3250, 2250)
314		childDestroyed.Children = []string{"S-001-A-G"}
315		grand := plainChild("S-001-A-G", "S-001-A", 1000, 1000)
316		l3 := &ledger{
317			Samples: map[string]*sampleRecord{
318				"S-001":     destroyedSample("S-001", 10000, 0, 6750, "S-001-A"),
319				"S-001-A":   childDestroyed,
320				"S-001-A-G": grand,
321			},
322		}
323		s3, err := Open(writeStructLedger(t, l3))
324		if err != nil {
325			t.Fatalf("子样后来销毁不改变父样已分出量，文件应正常恢复: %v", err)
326		}
327		parent, _ := s3.GetSample("S-001")
328		child, _ := s3.GetSample("S-001-A")
329		if parent.Destruction == nil || parent.Destruction.Qty != "6.750" {
330			t.Fatalf("父样销毁量应为 6.750: %+v", parent.Destruction)
331		}
332		if child.Destruction == nil || child.Destruction.Qty != "2.250" || child.Remaining != "0.000" {
333			t.Fatalf("子样销毁记录应独立保留为 2.250: %+v", child.Destruction)
334		}
335	}
