344	// TestOpenDestroyedAccountingIndependentAcrossRoots 同一份数据里的其他原样
345	// 不参与某次核对：原样 A 的销毁等式不成立时，即使原样 B 的记录完全正常，
346	// 也不能拿 B 的数量去凑 A 的差额（整份文件仍失败）；反之各自守恒时互不
347	// 影响、正常恢复。
348	func TestOpenDestroyedAccountingIndependentAcrossRoots(t *testing.T) {
349		// 各自守恒：A=10.000 分出 3.250 销毁 6.750；B=5.000 全部销毁。
350		good := &ledger{
351			Samples: map[string]*sampleRecord{
352				"A":   destroyedSample("A", 10000, 0, 6750, "A-C"),
353				"A-C": plainChild("A-C", "A", 3250, 3250),
354				"B":   destroyedSample("B", 5000, 0, 5000),
355			},
356		}
357		s, err := Open(writeStructLedger(t, good))
358		if err != nil {
359			t.Fatalf("两份原样各自守恒应正常恢复: %v", err)
360		}
361		a, _ := s.GetSample("A")
362		b, _ := s.GetSample("B")
363		if a.Destruction == nil || a.Destruction.Qty != "6.750" {
364			t.Fatalf("原样 A 销毁量错误: %+v", a.Destruction)
365		}
366		if b.Destruction == nil || b.Destruction.Qty != "5.000" {
367			t.Fatalf("原样 B 销毁量错误: %+v", b.Destruction)
368		}
369	
370		// A 的销毁量被错写成 10.000（多 3.250），不能用 B 的任何数量抵消。
371		bad := &ledger{
372			Samples: map[string]*sampleRecord{
373				"A":   destroyedSample("A", 10000, 0, 10000, "A-C"),
374				"A-C": plainChild("A-C", "A", 3250, 3250),
375				"B":   destroyedSample("B", 5000, 0, 5000),
376			},
377		}
378		mustRejectOpen(t, writeStructLedger(t, bad), "A", "10.000", "3.250")
379	}
