381	// TestOpenDestroyedAtLargeBounds 大数量边界：支持上限附近的合法销毁记录
382	// 必须逐位准确恢复；销毁量与直接子样初始量合计超出 int64 支持范围时按
383	// 无效数据拒绝，不能因数量过大忽略差额或接受回绕后的错误等式。
384	func TestOpenDestroyedAtLargeBounds(t *testing.T) {
385		const (
386			maxUnits   int64 = 9223372036854775807 // 9223372036854775.807 毫升
387			belowUnits int64 = 9223372036854775806 // 9223372036854775.806 毫升
388		)
389	
390		// 合法：初始量取上限，分出上限-0.001 的直接子样，销毁最后的 0.001，
391		// 合计恰好等于上限，重开后三位小数逐位一致。
392		legal := &ledger{
393			Samples: map[string]*sampleRecord{
394				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "BIG-C"),
395				"BIG-C": func() *sampleRecord {
396					c := plainChild("BIG-C", "BIG", belowUnits, belowUnits)
397					return c
398				}(),
399			},
400		}
401		s, err := Open(writeStructLedger(t, legal))
402		if err != nil {
403			t.Fatalf("上限附近的合法销毁记录应准确恢复: %v", err)
404		}
405		big, _ := s.GetSample("BIG")
406		if big.InitialQty != maxQtyString || big.Remaining != "0.000" ||
407			big.Destruction == nil || big.Destruction.Qty != "0.001" {
408			t.Fatalf("上限父样恢复不精确: %+v", big)
409		}
410		bigC, _ := s.GetSample("BIG-C")
411		if bigC.InitialQty != belowMaxString || bigC.Remaining != belowMaxString {
412			t.Fatalf("上限附近子样恢复不精确: init=%s remaining=%s",
413				bigC.InitialQty, bigC.Remaining)
414		}
415	
416		// 溢出场景一：销毁量 + 直接子样初始量在上限之外一个最小刻度
417		//（子样 上限-0.001，销毁 0.002：合计 上限+0.001），最终求和溢出，
418		// 必须按超出支持范围拒绝。
419		overflowFinal := &ledger{
420			Samples: map[string]*sampleRecord{
421				"BIG":   destroyedSample("BIG", maxUnits, 0, 2, "BIG-C"),
422				"BIG-C": plainChild("BIG-C", "BIG", belowUnits, belowUnits),
423			},
424		}
425		mustRejectOpen(t, writeStructLedger(t, overflowFinal), "BIG", "超出可表示范围")
426	
427		// 溢出场景二：各直接子样初始量累加本身溢出（子样合计超过上限），
428		// 在统计直接子样总量时即拒绝，不能回绕成一个小数量再去凑等式。
429		overflowChildren := &ledger{
430			Samples: map[string]*sampleRecord{
431				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "C1", "C2"),
432				"C1":  plainChild("C1", "BIG", belowUnits, belowUnits),
433				"C2":  plainChild("C2", "BIG", 2, 2),
434			},
435		}
436		mustRejectOpen(t, writeStructLedger(t, overflowChildren), "BIG", "超出可表示范围")
437	}
