453		child := plainChild("OLD-C", "OLD", 10000, 10000)
454		fresh := &sampleRecord{
455			ID: "NEW", Initial: 5000, Remaining: 5000, Holder: "h", Location: "l",
456			Children: []string{},
457			History: []historyRecord{{
458				Kind: "register", Time: registerCheckAt, Holder: "h", Location: "l",
459			}},
460		}
461		l := &ledger{
462			Samples: map[string]*sampleRecord{
463				"OLD":   exhausted,
464				"OLD-C": child,
465				"NEW":   fresh,
466			},
467		}
468		s, err := Open(writeStructLedger(t, l))
469		if err != nil {
470			t.Fatalf("无销毁信息的旧样品应按原规则恢复，不做销毁数量核对: %v", err)
471		}
472		old, _ := s.GetSample("OLD")
473		if old.Remaining != "0.000" || old.Destruction != nil {
474			t.Fatalf("旧样品剩余为零也不能补出销毁记录: %+v", old)
475		}
476		newSample, _ := s.GetSample("NEW")
477		if newSample.Destruction != nil || newSample.Remaining != "5.000" {
478			t.Fatalf("正常旧样品不应受新核对影响: %+v", newSample)
479		}
480	}
481	
482	// TestOpenRestoresParentAndChildDestructionViaAPI 端到端：通过公开操作产生
483	// 父子各自销毁的合法文件，重开后两份销毁记录独立保留，来源、人员、地点、
484	// 保管历史与销毁量都可查询，且恢复后操作限制与幂等行为保持兼容。
485	func TestOpenRestoresParentAndChildDestructionViaAPI(t *testing.T) {
486		dir := t.TempDir()
487		path := filepath.Join(dir, "data.json")
488		s, err := Open(path)
489		if err != nil {
490			t.Fatal(err)
491		}
492		s.now = func() time.Time { return registerCheckAt }
493		mustRegister(t, s, "P", "10.000", "张三", "A")
494		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
495			{ID: "C", Qty: "3.250"},
496		}}); err != nil {
497			t.Fatal(err)
498		}
499		parentAt := time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
500		if _, err := s.Destroy(DestroyInput{
501			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
502		}); err != nil {
503			t.Fatalf("销毁父样剩余 6.750: %v", err)
504		}
505		childAt := parentAt.Add(time.Hour)
506		if _, err := s.Destroy(DestroyInput{
507			SampleID: "C", Operator: "张三", Location: "A", At: childAt, Reason: "子样销毁",
508		}); err != nil {
509			t.Fatalf("销毁子样全部 3.250: %v", err)
510		}
511	
512		s2, err := Open(path)
513		if err != nil {
514			t.Fatalf("父子各自销毁的合法文件应正常恢复: %v", err)
515		}
516		p, err := s2.GetSample("P")
517		if err != nil {
518			t.Fatal(err)
519		}
520		c, err := s2.GetSample("C")
521		if err != nil {
522			t.Fatal(err)
523		}
524		if p.InitialQty != "10.000" || p.Remaining != "0.000" ||
525			p.Destruction == nil || p.Destruction.Qty != "6.750" ||
526			p.Destruction.Operator != "张三" || p.Destruction.Location != "A" ||
527			p.Destruction.Reason != "原样销毁" || !p.Destruction.At.Equal(parentAt) {
528			t.Fatalf("父样销毁记录恢复错误: %+v", p)
529		}
530		if len(p.Children) != 1 || p.Children[0] != "C" {
531			t.Fatalf("父样来源/子样关系应保留: %+v", p.Children)
532		}
533		if c.ParentID != "P" || c.InitialQty != "3.250" || c.Remaining != "0.000" ||
534			c.Destruction == nil || c.Destruction.Qty != "3.250" ||
535			c.Destruction.Reason != "子样销毁" || !c.Destruction.At.Equal(childAt) {
536			t.Fatalf("子样销毁记录恢复错误: %+v", c)
537		}
538	
539		// 恢复后销毁幂等与操作限制继续生效。
540		if _, err := s2.Destroy(DestroyInput{
541			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
542		}); err != nil {
543			t.Fatalf("恢复后相同销毁请求应幂等返回: %v", err)
544		}
545		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "X", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
546			t.Fatalf("恢复后已销毁父样仍不得分装, got %v", err)
547		}
548		if _, err := s2.Handover(HandoverInput{
549			TransferID: "T-X", SampleID: "C",
550			FromHolder: "张三", FromLocation: "A",
551			ToHolder: "李四", ToLocation: "B", HandedOverAt: childAt.Add(time.Hour),
552		}); !errors.Is(err, ErrConflict) {
553			t.Fatalf("恢复后已销毁子样仍不得发起交接, got %v", err)
554		}
555	
556		// 原始文件没有被恢复流程改写（仍为最后一次成功操作落盘的内容，
557		// 重新打开前后再次读取一致）。
558		raw, err := os.ReadFile(path)
559		if err != nil {
560			t.Fatal(err)
561		}
562		if !strings.Contains(string(raw), `"qty": 6750`) || !strings.Contains(string(raw), `"qty": 3250`) {
563			t.Fatalf("落盘文件应原样保留两份销毁量: %s", string(raw))
564		}
565	}
566

